14	export class KeyAndValueDuplicationError extends Error {
15	  constructor(key, value) {
16	    super(`(${key}, ${value})`);
17	    this.name = 'KeyAndValueDuplicationError';
18	    this.key = key;
19	    this.value = value;
20	  }
21	}
