23	export class KeyLookupError extends Error {
24	  constructor(key) {
25	    super(String(key));
26	    this.name = 'KeyLookupError';
27	    this.key = key;
28	  }
29	}
30	
31	const hasOwn = (obj, prop) => Object.prototype.hasOwnProperty.call(obj, prop);
