33	export class Bidict {
34	  constructor() {
35	    // forward index: key (string) -> value (bigint)
36	    this._fwd = Object.create(null);
37	    // inverse index: String(value) -> key (string); values are BigInt so
38	    // their decimal string form is a unique, collision-free object key.
39	    this._inv = Object.create(null);
40	    // insertion order of keys
41	    this._order = [];
42	  }
43	
44	  set(key, value) {
45	    if (hasOwn(this._fwd, key)) {
46	      const oldValue = this._fwd[key];
47	      if (oldValue === value) {
48	        // same key + same value: silent no-op
49	        return;
50	      }
51	      const valueKey = String(value);
52	      if (hasOwn(this._inv, valueKey)) {
53	        // existing key being set to a value held by a different key
54	        throw new KeyAndValueDuplicationError(key, value);
55	      }
56	      // overwrite in place, keeping the original insertion position
57	      delete this._inv[String(oldValue)];
58	      this._inv[valueKey] = key;
59	      this._fwd[key] = value;
60	      return;
61	    }
62	    const valueKey = String(value);
63	    if (hasOwn(this._inv, valueKey)) {
64	      // new key with a value already present under another key
65	      throw new ValueDuplicationError(value);
66	    }
67	    this._fwd[key] = value;
68	    this._inv[valueKey] = key;
69	    this._order.push(key);
70	  }
71	
72	  get(key) {
73	    if (!hasOwn(this._fwd, key)) {
74	      throw new KeyLookupError(key);
75	    }
76	    return this._fwd[key];
77	  }
78	
79	  invGet(value) {
80	    const valueKey = String(value);
81	    if (!hasOwn(this._inv, valueKey)) {
82	      throw new KeyLookupError(value);
83	    }
84	    return this._inv[valueKey];
85	  }
86	
87	  entries() {
88	    return this._order.map((key) => [key, this._fwd[key]]);
89	  }
90	}

