// Python repr() formatting helpers (str/int/dict/bidict).
// Pure ESM, no dependencies.

// Characters Python str.isprintable() treats as NON-printable:
// general categories Cc, Cf, Cs, Co, Cn, Zl, Zp, Zs (space U+0020 is handled
// separately and kept as-is).
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

function hexEscape(cp) {
  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

// Python repr() of a str.
export function reprStr(s) {
  // Quote selection: single quotes normally; double quotes if the string
  // contains a single quote but no double quote.
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === ' ') {
      out += ' ';
