// Minimal pure-JS reimplementation of the subset of the Python `bidict`
// package used by test8.py. No JavaScript `Map`: forward and inverse
// indexes are plain null-prototype objects, insertion order is kept in a
// parallel array of keys.

export class ValueDuplicationError extends Error {
  constructor(value) {
    super(String(value));
    this.name = 'ValueDuplicationError';
    this.value = value;
  }
}

export class KeyAndValueDuplicationError extends Error {
  constructor(key, value) {
    super(`(${key}, ${value})`);
    this.name = 'KeyAndValueDuplicationError';
    this.key = key;
    this.value = value;
  }
}

export class KeyLookupError extends Error {
  constructor(key) {
    super(String(key));
    this.name = 'KeyLookupError';
    this.key = key;
  }
}

const hasOwn = (obj, prop) => Object.prototype.hasOwnProperty.call(obj, prop);

export class Bidict {
  constructor() {
    // forward index: key (string) -> value (bigint)
    this._fwd = Object.create(null);
    // inverse index: String(value) -> key (string); values are BigInt so
    // their decimal string form is a unique, collision-free object key.
    this._inv = Object.create(null);
    // insertion order of keys
    this._order = [];
  }

  set(key, value) {
    if (hasOwn(this._fwd, key)) {
      const oldValue = this._fwd[key];
      if (oldValue === value) {
        // same key + same value: silent no-op
        return;
      }
      const valueKey = String(value);
      if (hasOwn(this._inv, valueKey)) {
        // existing key being set to a value held by a different key
        throw new KeyAndValueDuplicationError(key, value);
      }
      // overwrite in place, keeping the original insertion position
      delete this._inv[String(oldValue)];
      this._inv[valueKey] = key;
      this._fwd[key] = value;
      return;
    }
    const valueKey = String(value);
    if (hasOwn(this._inv, valueKey)) {
      // new key with a value already present under another key
      throw new ValueDuplicationError(value);
    }
    this._fwd[key] = value;
    this._inv[valueKey] = key;
    this._order.push(key);
  }

  get(key) {
    if (!hasOwn(this._fwd, key)) {
      throw new KeyLookupError(key);
    }
    return this._fwd[key];
  }

  invGet(value) {
    const valueKey = String(value);
    if (!hasOwn(this._inv, valueKey)) {
      throw new KeyLookupError(value);
    }
    return this._inv[valueKey];
  }

  entries() {
    return this._order.map((key) => [key, this._fwd[key]]);
  }
}
