// Resolve a long option prefix (argparse._get_option_tuples, long
// branch): every known long option string starting with the prefix is
// a candidate, in definition order.
function matchLongPrefix(prefix) {
  const matches = [];
  for (const optString of OPTION_STRINGS) {
    if (optString.startsWith('--') && optString.startsWith(prefix)) {
      matches.push(optString);
    }
  }
  return matches;
}

export function parseArgs(argv, prog) {
  const values = Object.create(null);
  const seen = Object.create(null);
  const extras = [];
  let afterDoubleDash = false;

  let i = 0;
  while (i < argv.length) {
    const tok = argv[i];

    if (afterDoubleDash) {
      extras.push(tok);
      i += 1;
      continue;
    }

    // '--' stops option processing; this argparse version keeps the
    // '--' token itself in the unrecognized arguments.
    if (tok === '--') {
      afterDoubleDash = true;
      extras.push(tok);
      i += 1;
      continue;
    }

    // Not option-like: a positional; this parser defines none.
    if (!looksLikeOption(tok)) {
      extras.push(tok);
      i += 1;
      continue;
    }

    // Split an explicit "=value" suffix.
    let base = tok;
    let explicit = null;
    const eq = tok.indexOf('=');
    if (tok.startsWith('--') && eq !== -1) {
      base = tok.slice(0, eq);
      explicit = tok.slice(eq + 1);
    }

    let action = null;
    let explicitArg = explicit;

    if (Object.prototype.hasOwnProperty.call(ACTIONS, base)) {
      action = ACTIONS[base];
    } else if (tok.startsWith('--')) {
      const matches = matchLongPrefix(base);
      if (matches.length > 1) {
        errorAndExit(
          prog,
          `ambiguous option: ${tok} could match ${matches.join(', ')}`
        );
      } else if (matches.length === 1) {
        action = ACTIONS[matches[0]];
      }
      // no match: unknown optional -> extra
    } else if (eq !== -1 && Object.prototype.hasOwnProperty.call(ACTIONS, tok.slice(0, eq))) {
      // single-dash form with '=', e.g. -h=x
      action = ACTIONS[tok.slice(0, eq)];
      explicitArg = tok.slice(eq + 1);
    } else if (tok.slice(0, 2) === '-h') {
      // concatenated short option, e.g. -hx: -h takes no argument, so
      // the rest would be re-parsed as more short options (landing in
      // extras), but the help action fires first.
      action = ACTIONS['-h'];
      explicitArg = tok.slice(2);
      if (explicitArg !== '' && explicitArg[0] !== '-' && eq === -1) {
        printHelpAndExit(prog);
      }
      if (explicitArg === '') explicitArg = null;
    }

    if (action === null) {
      extras.push(tok);
      i += 1;
      continue;
    }

    if (action.kind === 'help') {
      if (explicitArg !== null) {
        errorAndExit(
          prog,
          `argument -h/--help: ignored explicit argument ${reprStr(explicitArg)}`
        );
      }
      printHelpAndExit(prog);
    }

    // store action: needs exactly one value
    let raw;
    if (explicitArg !== null) {
      raw = explicitArg;
      i += 1;
    } else if (i + 1 < argv.length && !looksLikeOption(argv[i + 1]) && argv[i + 1] !== '--') {
      raw = argv[i + 1];
      i += 2;
    } else {
      errorAndExit(prog, `argument ${action.display}: expected one argument`);
    }

    if (action.type === 'int') {
      const parsed = parsePythonInt(raw);
      if (parsed === null) {
        errorAndExit(
          prog,
          `argument ${action.display}: invalid int value: ${reprStr(raw)}`
        );
      }
      values[action.dest] = parsed;
    } else {
      values[action.dest] = raw;
    }
    seen[action.dest] = true;
  }

  // argparse checks required arguments before reporting extras.
  const missing = [];
  for (const dest of REQUIRED) {
    if (!seen[dest]) missing.push('--' + dest);
  }
  if (missing.length > 0) {
    errorAndExit(
      prog,
      `the following arguments are required: ${missing.join(', ')}`
    );
  }

  if (extras.length > 0) {
    errorAndExit(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return {
    k1: values.k1,
    v1: values.v1,
    k2: values.k2,
    v2: values.v2,
    k3: values.k3,
    v3: values.v3,
  };
}
